def pick(value,support,contra,confidence='medium'):
    return {'pick':value,'confidence':confidence if value is not None else None,
            'status':'provisional' if value is not None else 'observasi',
            'supporting_evidence':support,'contradicting_evidence':contra,
            'abstain_reason':'; '.join(contra) if value is None else None}


def choices(focus,scenario,one,btts,total):
    return {'targets':{'1x2':one,'btts':btts,'total_2_5':total},'focus_target':focus,'score_scenario':scenario}


